def test_cancelled_preparation_owner_proof_is_executor_independent():
    repo_root = Path(__file__).resolve().parents[3]
    child = (
        "import asyncio, concurrent.futures, runpy, sys, threading\n"
        "from pathlib import Path\n"
        "repo = Path(sys.argv[1])\n"
        'sys.path[:0] = [str(repo / "agents/tests/blackbox"), str(repo / "agents")]\n'
        "namespace = runpy.run_path(sys.argv[2])\n"
        "import benchmarks.run_benchmark\n"
        "import benchmarks.browser_zero_allocation\n"
        "release = threading.Event()\n"
        'executor = concurrent.futures.ThreadPoolExecutor(thread_name_prefix="owned-proof-control")\n'
        "ready = [threading.Event() for _ in range(executor._max_workers)]\n"
        "def occupy(signal):\n"
        "    signal.set()\n"
        "    release.wait()\n"
        "async def run():\n"
        "    asyncio.get_running_loop().set_default_executor(executor)\n"
        "    for signal in ready:\n"
        "        executor.submit(occupy, signal)\n"
        "    try:\n"
        '        assert all(signal.wait(5) for signal in ready), "owned blockers did not start"\n'
        '        await namespace["test_cancelled_preparation_archives_only_with_positive_task_and_owner_proof"]()\n'
        '        assert not release.is_set(), "executor contention removed before ownership proof"\n'
        "    finally:\n"
        "        release.set()\n"
        "asyncio.run(run())\n"
    )
    result = subprocess.run(
        [sys.executable, "-c", child, str(repo_root), str(Path(__file__).resolve())],
        cwd=repo_root,
        text=True,
        capture_output=True,
        check=False,
        timeout=NATIVE_VERIFICATION_TIMEOUT_SECONDS,
    )
    assert result.returncode == 0, result.stdout + result.stderr


def test_agent_messages_have_browser_terminal_requires_explicit_close():
    """FINISHED recording alone must not count as a browser-panel terminal.

    FE computeActiveBrowserPanels ignores recording/network_recording cleanup
    rows. Hotel k=5 hub archives (2026-08-31) had FINISHED recordings with an
    IN_PROGRESS browser row and no task_complete — every FE link kept an active
    chip. The archive refresh helper must wait for an explicit terminal.
    """
    import benchmarks.run_benchmark as bench

    task_id = "task-hotel-1"
    open_only = [
        {
            "metadata": {
                "toolName": "spawn_browser_agent",
                "action_type": "browser",
                "toolStatus": "IN_PROGRESS",
                "task_id": task_id,
            }
        },
        {
            "metadata": {
                "toolName": "spawn_browser_agent",
                "action_type": "recording",
                "toolStatus": "FINISHED",
                "task_id": task_id,
                "recording_view_url": "https://kernel.example/replay",
            }
        },
    ]
    assert not bench._agent_messages_have_browser_terminal(open_only)

    with_terminal = open_only + [
        {
            "metadata": {
                "toolName": "spawn_browser_agent",
                "action_type": "task_complete",
                "toolStatus": "FINISHED",
                "task_id": task_id,
            }
        }
    ]
    assert bench._agent_messages_have_browser_terminal(with_terminal)

    tool_call_scoped = [
        {
            "metadata": {
                "toolName": "spawn_browser_agent",
                "action_type": "session_paused",
                "toolStatus": "ERROR",
                "toolCallId": "tool-1",
            }
        }
    ]
    assert bench._agent_messages_have_browser_terminal(tool_call_scoped)
    assert bench._agent_messages_have_browser_terminal([])


def test_agent_messages_ready_for_browser_hub_archive_waits_for_recording():
    """session_paused alone must not archive before Kernel replay is attached.

    DoorDash grocery timeout 3afbbda8 (2026-09-02): cleanup posted session_paused
    without task_id, the refresh helper returned early, and the hub bundle missed
    the FINISHED recording_view_url that landed ~1s later. FE Recording tab empty.
    """
    import benchmarks.run_benchmark as bench

    task_id = "task-dd-1"
    recording_started = {
        "metadata": {
            "toolName": "spawn_browser_agent",
            "action_type": "recording",
            "toolStatus": "IN_PROGRESS",
            "task_id": task_id,
        }
    }
    session_paused = {
        "metadata": {
            "toolName": "spawn_browser_agent",
            "action_type": "session_paused",
            "toolStatus": "ERROR",
            "toolCallId": "tool-timeout-1",
        }
    }
    recording_finished = {
        "metadata": {
            "toolName": "spawn_browser_agent",
            "action_type": "recording",
            "toolStatus": "FINISHED",
            "task_id": task_id,
            "recording_view_url": "https://kernel.example/replay.mp4",
        }
    }

    paused_before_recording = [recording_started, session_paused]
    assert bench._agent_messages_have_browser_terminal(paused_before_recording)
    assert not bench._agent_messages_have_browser_recording_ready(paused_before_recording)
    assert not bench._agent_messages_ready_for_browser_hub_archive(paused_before_recording)

    paused_with_recording = [recording_started, recording_finished, session_paused]
    assert bench._agent_messages_ready_for_browser_hub_archive(paused_with_recording)
    assert bench._agent_messages_ready_for_browser_hub_archive([])


def _resumed_recording_archive_rows():
    # Captured a806f2a9: saved first part, resumed the SAME browser task, then
    # paused before the resumed part was attached. No real media is fabricated.
    identity = dict(
        toolName="spawn_browser_agent",
        task_id="owned-resumed-browser",
        workflowGeneration="owned-root-generation",
        browser_url="https://fixture.kernel.sh/browser/live/owned-session",
        browser_session_metadata={"provider": "kernel"},
    )

    def row(action, status, **extra):
        return {"metadata": dict(identity, action_type=action, toolStatus=status, **extra)}

    first = row("recording", "IN_PROGRESS", toolCallId="first-start")
    saved = row(
        "recording",
        "FINISHED",
        toolCallId="first-saved",
        recording_view_url="https://fixture.invalid/first-part",
    )
    resumed = row("recording", "IN_PROGRESS", toolCallId="resumed-start")
    terminal = row("task_complete", "ERROR", toolCallId="owned-tool")
    latest = row(
        "recording",
        "FINISHED",
        toolCallId="resumed-saved",
        recording_view_url="https://fixture.invalid/resumed-part",
    )
    return [first, saved, resumed, terminal], latest


def test_browser_archive_requires_each_resumed_recording_part():
    from copy import deepcopy
    import benchmarks.run_benchmark as bench

    rows, latest = _resumed_recording_archive_rows()
    before = deepcopy(rows)
    assert not bench._agent_messages_have_browser_recording_ready(rows), (
        "earlier task recording concealed missing resumed part"
    )
    assert not bench._agent_messages_ready_for_browser_hub_archive(rows)
    assert not bench._agent_messages_ready_for_durable_browser_evidence(rows)
    assert rows == before, "readiness mutated captured transcript"
    complete = rows + [latest]
    assert bench._agent_messages_ready_for_browser_hub_archive(complete)
    assert bench._agent_messages_ready_for_durable_browser_evidence(complete)
    assert not bench._agent_messages_ready_for_durable_browser_evidence([rows[0], rows[2], latest, rows[3]]), (
        "a later saved part concealed an earlier missing part"
    )
    for field, value in (
        ("workflowGeneration", "foreign-generation"),
        ("browser_url", "https://fixture.kernel.sh/browser/live/foreign-session"),
    ):
        foreign = deepcopy(latest)
        foreign["metadata"][field] = value
        assert not bench._agent_messages_ready_for_durable_browser_evidence(rows + [foreign]), field
    empty = deepcopy(latest)
    empty["metadata"].pop("recording_view_url")
    assert not bench._agent_messages_ready_for_durable_browser_evidence(rows + [empty])


async def test_browser_archive_refresh_waits_for_resumed_recording_part():
    from copy import deepcopy
    import benchmarks.run_benchmark as bench

    rows, latest = _resumed_recording_archive_rows()
    root = "owned-root-generation"
    incomplete = {"agent": {"status": "PAUSED"}, "messages": rows}
