async def test_minted_benchmark_preserves_child_harness_outcomes():
    """A cancelled or broken child cannot become an ordinary aggregate failure."""
    from unittest.mock import AsyncMock
    import benchmarks.run_benchmark as bench
    from benchmarks.results import TaskResult

    for stage in ("biometrics", "post"):
        for outcome, expected in (
            ("FAILED", "FAILED"),
            ("ERROR", "ERROR"),
            ("CANCELLED", "CANCELLED"),
            ("INFRA_ERROR", "INFRA_ERROR"),
            ([], "ERROR"),
            ("UNRECOGNIZED", "ERROR"),
            ("PASSED", "ERROR"),
        ):
            child = TaskResult(
                name="child",
                passed=False,
                agent_id="child-agent",
                status="ACTIVE",
                benchmark_status=outcome,
                progress_score=0,
                duration_seconds=1,
                cost_cents=0,
                message_count=1,
            )
            with contextlib.ExitStack() as stack:
                stack.enter_context(
                    patch.dict(
                        os.environ,
                        {
                            "BENCHMARK_MINTED_TARGET_URL": "https://x.com",
                            "BENCHMARK_MINTED_AUTH_REALM": "x.com",
                            "BENCHMARK_MINTED_CLEAR_EXISTING_AUTH": "false",
                        },
                    )
                )
                for name, value in (
                    ("_local_agent_identity_present_for_user", True),
                    ("_delete_local_minted_accounts_for_user", 0),
                    ("_seed_local_benchmark_agent_identity_if_missing", None),
                    ("_disable_local_auth_material_for_realm", 0),
                    ("_get_local_minted_account", None),
                    ("_auth_bundle_biometrics_gate_enabled", stage == "biometrics"),
                ):
                    stack.enter_context(patch.object(bench, name, return_value=value))
                stack.enter_context(
                    patch.object(bench, "_run_auth_bundle_biometrics_gate", AsyncMock(return_value=child))
                )
                stack.enter_context(patch.object(bench, "run_single_task", AsyncMock(return_value=child)))
                result = await bench.run_minted_agent_account_task(
                    "http://127.0.0.1:32001", bench.get_task_by_name("minted-agent-accounts-x")
                )
            assert result.passed is False
            assert result.benchmark_status == expected, (stage, outcome, result.benchmark_status)


def test_bad_amazon_password_fixture_upserts_on_the_browser_password_unique_key():
    """The forced bad-password fixture must name BrowserPassword's real unique key.

    Postgres rejects an ON CONFLICT target that matches no unique index, so a
    fixture left on the old (userId, origin, username) key fails outright once
    saved logins are unique per browser source and profile.
    """
    import re

    import benchmarks.run_benchmark as bench

    schema = (Path(__file__).resolve().parents[3] / "back-end" / "prisma" / "schema.prisma").read_text()
    model = re.search(r"model BrowserPassword \{(.*?)\n\}", schema, re.S)
    assert model is not None
    unique = re.search(r"@@unique\(\[([^\]]+)\]\)", model.group(1))
    assert unique is not None
    expected = [column.strip() for column in unique.group(1).split(",")]

    queries = []
    original_run_sql = bench._run_local_victoria_sql
    try:
        bench._run_local_victoria_sql = lambda sql: queries.append(sql) or "bundle-id\tpwd-1\tpwd-2"
        fixture = bench._seed_local_bad_amazon_auth_scenario("user-123", "amazon.com")
    finally:
        bench._run_local_victoria_sql = original_run_sql

    assert fixture["password_ids"] == ["pwd-1", "pwd-2"]
    password_inserts = re.findall(
        r'INSERT INTO "BrowserPassword".*?ON CONFLICT \(([^)]*)\)', queries[0], re.S
    )
    assert len(password_inserts) == 2
    for target in password_inserts:
        assert [column.strip().strip('"') for column in target.split(",")] == expected


