    assert 'FROM "CookieBundle"' in queries[0]
    assert 'FROM "BrowserPassword"' in queries[0]
    assert 'FROM "PasskeyCredential"' in queries[1]
    assert 'UPDATE "PasskeyCredential"' not in queries[1]
