async def test_agentcard_release_skip_catalog_owned_cleanup_stays_strict():
    """Known sandbox/live release stalls warn and skip; unknown tasks and mismatched modes fail."""
    from unittest.mock import AsyncMock

    from benchmarks import run_benchmark as bench

    root = "00000000-0000-4000-8000-000000000021"
    row = {
        "purchase_id": "571cab13-0531-4173-85ef-d0709227fcd8",
        "agent_id": root,
        "status": "HELD",
        "card_id": "card_b2e87905c62c34ba8abff4d4",
        "stripe_payment_intent_id": "pi_test",
        "total_cents": 4396,
        "funding_status": "RECLAIMING",
        "provider_transfer_id": "owt_ff135698c18b095f3a40a249",
        "reclaim_provider_transfer_id": None,
    }

    async def stalled_payments(_base_url, _root_id, evidence):
        evidence["payment_snapshot"] = {"tree_agent_ids": [root], "purchase_cleanup": [row]}
        raise TimeoutError()

    async def finalize(env: dict, lifecycle: dict, task_name: str = "agent-payment-test-shop") -> tuple:
        result = bench.TaskResult(
            name=task_name,
            passed=True,
            agent_id=root,
            status="COMPLETED",
            progress_score=1,
            duration_seconds=1,
            cost_cents=0,
            message_count=0,
            logs={"tree": {root: {}}},
        )
        before = {"root_user_id": "test-owned-user", "tree_agent_ids": [root], "browser_sessions": []}
        with (
            patch.dict(os.environ, env),
            patch.object(bench.cloud_batch_cleanup, "exact_root_sessions", return_value=before),
            patch.object(bench.cloud_batch_cleanup, "close_exact_root_sessions", return_value={}),
            patch.object(bench, "pause_agent", AsyncMock(return_value=True)),
            patch.object(bench, "delete_agent", AsyncMock(return_value=True)),
            patch.object(bench, "_refresh_browser_archive_snapshot", AsyncMock(return_value={})),
            patch.object(bench, "finalize_archive_and_score_world_model", AsyncMock(return_value=("ref", None))),
            patch.object(bench, "_finalize_owned_root_payments", stalled_payments),
            patch.object(bench, "get_test_payment_lifecycle", AsyncMock(return_value=lifecycle)),
            patch.object(bench, "fetch_local_worker_logs", return_value=[]),
        ):
            try:
                await bench._finalize_owned_cloud_batch("test-owned-no-network", [result], {})
            except RuntimeError as error:
                return result, error
        return result, None

    flag = {"BENCHMARK_SKIP_AGENTCARD_RELEASE_STALL": "1"}
    result, error = await finalize(flag, _agentcard_release_stall_lifecycle())
    assert error is None
    assert (result.passed, result.status, result.benchmark_status) == (False, "SKIPPED", "SKIPPED")
    assert result.failure_reason.startswith(bench.AGENTCARD_RELEASE_SKIP_REASON)
    evidence = result.logs["cloud_cleanup_evidence"]
    assert evidence["errors"] == []
    assert evidence["warnings"] == [f"payment: {bench.AGENTCARD_RELEASE_SKIP_REASON}"]
    assert evidence["agentcard_release_stall_lifecycles"][root]["orgTransfer"]["releasedCents"] == 0

    with patch.dict(os.environ):
        os.environ.pop(bench.AGENTCARD_RELEASE_SKIP_ENV, None)
        for name, live in (("agent-payment-test-shop", False), ("agent-payment-production-abandonment", True)):
            row["total_cents"] = 100 if live else 4396
            result, error = await finalize({}, _agentcard_release_stall_lifecycle(livemode=live), name)
            assert error is None, (name, error)
            assert (result.passed, result.status, result.benchmark_status) == (False, "SKIPPED", "SKIPPED"), name
            assert result.logs["cloud_cleanup_evidence"]["errors"] == []
            assert result.logs["cloud_cleanup_evidence"]["warnings"] == [
                f"payment: {bench.AGENTCARD_RELEASE_SKIP_REASON}"
            ]
            assert bench._ci_should_fail({"failed": 0, "skipped": 1}, [result]) is False
        row["total_cents"] = 4396

    for env, lifecycle in (
        ({"BENCHMARK_SKIP_AGENTCARD_RELEASE_STALL": "0"}, _agentcard_release_stall_lifecycle()),
        (flag, _agentcard_release_stall_lifecycle(livemode=True)),
        (flag, _agentcard_release_stall_lifecycle(cardId="card_someone_else")),
    ):
        result, error = await finalize(env, lifecycle)
        assert error is not None and "owned cloud evidence finalization failed" in str(error), lifecycle
        assert (result.passed, result.benchmark_status) == (False, "ERROR")
        assert result.logs["cloud_cleanup_evidence"]["errors"] == ["payment: TimeoutError"]

    for name in ("agent-payment-production-abandonment", "unregistered-agentcard-task"):
        result, error = await finalize(flag, _agentcard_release_stall_lifecycle(), name)
        assert error is not None and "owned cloud evidence finalization failed" in str(error), name
        assert (result.passed, result.benchmark_status) == (False, "ERROR"), name
        assert result.logs["cloud_cleanup_evidence"]["errors"] == ["payment: TimeoutError"]
        assert result.logs["cloud_cleanup_evidence"]["warnings"] == []


def test_fly_infra_detector_ignores_collector_placeholders():
    """A '[fly.io] 0 logs ... (N total captured)' placeholder is not a log line.

    Regression: on --local runs the prod Fly stream never contains local agents,
    and a captured-line count containing "429" made every agent an INFRA ERROR.
    """
    import benchmarks.logs as bench_logs
    from benchmarks.run_benchmark import _detect_infra_errors_from_fly

    class _Collector:
        def get_logs_for_agent(self, agent_id):
            if agent_id == "real":
                return ["2026-10-19T03:00:00Z worker got 429 Too Many Requests from provider"]
            return [f"[fly.io] 0 logs for agent {agent_id[:12]} (674429 total captured)"]

    previous = bench_logs._fly_collector
    bench_logs._fly_collector = _Collector()
    try:
        assert _detect_infra_errors_from_fly(["placeholder-agent"]) == []
        assert len(_detect_infra_errors_from_fly(["real"])) == 1
    finally:
        bench_logs._fly_collector = previous


# Native elapsed-clock owning regression: real _poll_agent, only external edges fake.
async def _clock_poll_case(
    name, wall_delta, elapsed_delta, status="COMPLETED", expect_timeout=False, mode=None, next_times=()
):
    from copy import deepcopy
    from types import SimpleNamespace
    from contextlib import ExitStack
    from benchmarks import run_benchmark as bench
    from benchmarks.benchmark_tasks import get_task_by_name
    import socket
    import hashlib

    task = deepcopy(get_task_by_name(name))
    if name.startswith("browser-auth-"):
        assert task.timeout_seconds in (900, 1200)
    task.approval_handling = "ignore"

    class Clock:
        def __init__(self):
            self.calls = {"wall": 0, "elapsed": 0}
            self.wall = 10000 + wall_delta
            self.elapsed = 20000 + elapsed_delta

        def time(self):
            self.calls["wall"] += 1
            return 10000 if self.calls["wall"] == 1 else self.wall

        def monotonic(self):
            self.calls["elapsed"] += 1
            return 20000 if self.calls["elapsed"] == 1 else self.elapsed

    clock = Clock()
    reads = []
    pending = list(next_times)
    denial = []
    payment = []

    async def read(*args):
        reads.append(1)
        msgs = [{"role": "USER", "text": str(i)} for i in range(len(reads))] if mode == "progress" else []
        if mode == "chat":
            msgs = [{"role": "ASSISTANT", "text": "answer"}]
        if mode == "payment":
            msgs = [{"role": "TOOL", "metadata": {"title": "Payment card ready"}}]
        return {"agent": {"id": "00000000-0000-4000-8000-000000000001", "status": status}, "messages": msgs}

    async def sleep(*args):
        if not pending:
            raise AssertionError("poll did not terminate on declared clock schedule")
        clock.wall, clock.elapsed = pending.pop(0)

    async def tree(*args):
        return {
            "total_messages": len(reads) if mode == "progress" else 0,
            "agent_count": 1,
            "total_cost_cents": 0,
            "failed_count": 0,
            "error_agents": [],
            "all_agents": [
                {
                    "agent_id": "00000000-0000-4000-8000-000000000001",
                    "message_count": len(reads) if mode == "progress" else 0,
                    "status": status,
                }
            ],
        }

    def deny(*args, **kwargs):
        denial.append("external")
        raise AssertionError("external network forbidden")

    async def start_payment(*args):
        return {"status": "pending"}

    async def wait_payment(*args, **kwargs):
        payment.append(kwargs["timeout_seconds"])
        return {"status": "reclaimed"}

    if mode == "chat":
        task.is_chat_mode = True
    if mode == "payment":
        task.payment_card_request_action = "abandon"
    with ExitStack() as stack:
        for target, attr, value in [
            (socket.socket, "connect", deny),
            (socket, "getaddrinfo", deny),
            (bench, "time", clock),
            (bench, "get_agent", read),
            (bench, "get_attention_requests", AsyncMock(return_value=[])),
            (bench, "_fetch_tree_stats", tree),
            (bench, "_fetch_message_counts", AsyncMock(return_value={})),
            (bench, "_detect_infra_errors_from_fly", lambda *args: []),
            (bench, "_mark_expected_gate_from_data", lambda *args: None),
            (bench, "_start_payment_abandonment_with_recovery", start_payment),
            (bench, "_wait_for_expected_payment_lifecycle", wait_payment),
            (bench.asyncio, "sleep", sleep),
        ]:
            stack.enter_context(patch.object(target, attr, value))
        result = await bench._poll_agent("http://offline.invalid", "00000000-0000-4000-8000-000000000001", task)
    assert denial == []
    assert result[0]["agent"]["status"] == status
    reason = result[3]
    assert bool(reason and reason.startswith("Timeout after")) is expect_timeout, (mode, reason)
    if mode == "stall":
        assert reason and "tree stalled" in reason
    if mode == "payment":
        assert reason is None and payment == [min(420, task.timeout_seconds - elapsed_delta)]
    if mode == "progress":
        assert len(reads) == 3 and reason is not None
    if mode == "chat":
        assert len(reads) == 2 and reason is None
    return result


async def _clock_deadline_cases(name, limit):
    if True:
        for wall, elapsed, status, expired in [
            (30, 30, "COMPLETED", False),
            (30, 30, "FAILED", False),
            (2900, 30, "COMPLETED", False),
            (-2900, 30, "COMPLETED", False),
            (limit + 1, limit + 1, "ACTIVE", True),
            (limit + 1, limit + 1, "COMPLETED", True),
            (-2900, limit + 1, "COMPLETED", True),
        ]:
            await _clock_poll_case(name, wall, elapsed, status, expired)


